package com.quizapp.security;import org.springframework.stereotype.Component;import org.springframework.security.core.Authentication;import com.quizapp.repository.UserRepository;
@Component("hostAuthorization") public class HostAuthorization {private final UserRepository users;public HostAuthorization(UserRepository u){users=u;}public boolean approved(Authentication a){if(a==null||!a.isAuthenticated())return false;return users.findById(a.getName()).map(u->"HOST".equals(u.getRole())&&"ACTIVE".equals(u.getAccountStatus())&&"APPROVED".equals(u.getHostApprovalStatus())).orElse(false);}}
